import PyPDF2
import io

# Get the PDF file from the previous node
try:
    pdf_data = items[0]['binary']['data']
    file_name = items[0]['json']['fileName'] if 'fileName' in items[0]['json'] else 'document.pdf'
except:
    # Fallback if binary data structure is different
    pdf_data = items[0]['binary']
    file_name = 'document.pdf'

try:
    # Create a BytesIO object from the binary data
    pdf_file = io.BytesIO(pdf_data)

    # Create PDF reader
    pdf_reader = PyPDF2.PdfReader(pdf_file)

    # Extract text from all pages
    full_text = ""
    page_count = len(pdf_reader.pages)

    for page_num in range(page_count):
        page = pdf_reader.pages[page_num]
        page_text = page.extract_text()
        full_text += f"\n--- Page {page_num + 1} ---\n{page_text}\n"

    print(f"📄 Successfully extracted text from {file_name} ({page_count} pages)")
    print(f"Total characters extracted: {len(full_text)}")

    return [{
        'json': {
            'file_name': file_name,
            'page_count': page_count,
            'text_length': len(full_text),
            'extracted_text': full_text,
            'extraction_success': True
        }
    }]

except Exception as e:
    print(f"❌ Error extracting text from {file_name}: {str(e)}")
    return [{
        'json': {
            'file_name': file_name,
            'extraction_success': False,
            'error': str(e),
            'extracted_text': ''
        }
    }]

